output_text:
[
  {
    "id": "must_take_cart_at_entrance",
    "text": "A shopper is obliged to take the available entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "at_entrance_cart",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_pickup_without_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "using_cart_storage": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_to_bay",
    "text": "After taking a cart, the shopper is obliged to return it to the designated cart-return bay at cell (0,1) before leaving.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "at_cart_return_bay": "at(0,1)",
        "cart_parked_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "cartAt(1,5)"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "holding_cart",
              "at_cart_return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere except the designated return bay at (0,1).",
    "abstraction": {
      "state_properties": {
        "at_cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "at(0,1)"
        }
      },
      "events": {
        "leave_cart_away_from_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is prohibited from exiting the supermarket while still in possession of the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "not_holding_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "holding_cart"
            ]
          },
          "post": null
        },
        "exit_without_cart": {
          "pre": {
            "and": [
              "EXIT",
              "not_holding_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "no_carts_in_eastern_exit_zone",
    "text": "Store carts are prohibited in the eastern exit-side area, so shoppers must park the cart before walking to the exit.",
    "abstraction": {
      "state_properties": {
        "eastern_exit_zone": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_eastern_exit_zone": {
          "and": [
            "hasCart",
            "eastern_exit_zone"
          ]
        }
      },
      "events": {
        "push_cart_into_eastern_exit_zone": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "eastern_exit_zone"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_eastern_exit_zone"
    }
  },
  {
    "id": "no_shopping_after_cart_return",
    "text": "Once the cart has been returned to the bay, the shopper is prohibited from performing further shopping interactions and should only proceed to the exit.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)",
        "not_at_exit": {
          "not": "at(9,5)"
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT",
              "not_at_exit"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
